    ciphertext = f.read()

# Try XOR decryption with printable byte keys
print("\n--- Trying XOR Decryption ---")
for key in range(256):
    decrypted = bytes([b ^ key for b in ciphertext])
    try:
        decoded = decrypted.decode("utf-8")
        if "flag{" in decoded:
            print("FLAG FOUND:", decoded)
    except UnicodeDecodeError:
        continue

# Try Caesar cipher decryption by brute-forcing shifts
print("\n--- Trying Caesar Cipher Decryption ---")
def caesar(data, shift):
    decrypted = ''.join(chr((byte - shift) % 256) for byte in data)
    return decrypted

for shift in range(256):
    try:
        result = caesar(ciphertext, shift)
        if "flag{" in result:
            print("FLAG FOUND:", result)
